import logging
from taf.ul.power_ue.devices.taf_ue_device import TafUeDevice
from taf.ul.power_ue.devices.device_class import PowerUeDevice
from taf.config.testline.ue import TafUeAndroid
from taf.ul.power_ue.devices.qualcomm.force_port_available import AppserverForcePortAvailable


class Qualcomm(PowerUeDevice):
    """
    Basic method with official solution taf.ue.proxy.

    """

    def __init__(
        self, ue_config, tl=None, robot_logs_dir=None, **kwargs
    ):
        super(Qualcomm, self).__init__(ue_config, **kwargs)
        if isinstance(ue_config, TafUeAndroid):
            self.solution = "android"
        else:
            self.solution = "at"
        self.qualcomm_object = TafUeDevice(
            ue_config=ue_config, tl=tl, robot_logs_dir=robot_logs_dir
        )

    def prepare(self, ue_alias, **kwargs):
        """
        Prepare UE for L3 call.
        """
        self.qualcomm_object.prepare(ue_alias)

    def teardown(self):
        """
        Teardown UE for L3 call.
        """
        self.qualcomm_object.teardown()

    def attach(self, timeout=30, **kwargs):
        """
        Attach UE for L3 call.
        """
        self.qualcomm_object.attach(timeout)
        if self.solution == "at":
            logging.info("Create pdu session as using AT")
            self.qualcomm_object.create_pdu_session()

    def verify_attach(self, timeout=60, apn=None, cell_id=None, **kwargs):
        """
        Verify attach result when plugin verify itself insufficiently.
        """
        self.qualcomm_object.verify_attach(
            timeout=timeout,
            apn=apn,
            cell_id=cell_id,
            ue_info_dict={"pci": "PCI", "ips": "IPS", "cell_id": "cell_id"},
        )

    def reboot(self, timeout=180, **kwargs):
        """
        reboot UE for L3 call.
        """
        self.qualcomm_object.reboot(timeout=timeout)

    def detach(self, **kwargs):
        """
        Detach UE for L3 call.
        """
        if self.solution == "at":
            logging.info("Release pdu session as using AT")
            self.qualcomm_object.release_pdu_session()
        self.qualcomm_object.detach()

    def start_traffic(
        self,
        dt_name,
        direction,
        duration=10,
        throughput=10.0,
        protocol="udp",
        iperf_port=None,
        check_dt_alive_timeout=None,
        iperf_options=None,
        **kwargs
    ):
        """
        Start L3 data transfer

        :param dt_name: str, alias name for created data transfer.
        :param direction: str, traffic direction, 'ul', 'dl'.
        :param duration: Optional[int], Duration of traffic, 10 as default means 10s.
        :param throughput: Optional[float], Bandwidth to send in Mbps!!
        :param protocol: Optional[str], Traffic protocol type. E.G udp/tcp, 'udp' as default.
        :param iperf_port: Optional[str], port number used for traffic start via iperf, None as default.
        :param check_dt_alive_timeout: Optional[dict], iperf parameter options, None as default.
        :param iperf_options: Optional[int], time after start traffic to check dt alive, None as default.

        Returns:

        """
        if iperf_options and self.solution == "android":
            logging.info("Convert iperf_options values to string value for taf.ue.android")
            for key in iperf_options:
                iperf_options[key] = str(iperf_options[key])
        if self.solution == "at":
            AppserverForcePortAvailable(self.ue_config).force_port_available(port=iperf_port)
        self.qualcomm_object.start_traffic(
            dt_name=dt_name,
            direction=direction,
            duration=duration,
            throughput=throughput,
            protocol=protocol,
            iperf_port=iperf_port,
            check_dt_alive_timeout=check_dt_alive_timeout,
            iperf_options=iperf_options,
        )

    def stop_traffic(self, dt_name, **kwargs):
        """
        Stop data transfer for L3 call.

        :param dt_name: str, alias name for stop data transfer.
        """
        self.qualcomm_object.stop_traffic(dt_name=dt_name)

    def check_unidirectional_throughput(
        self,
        dt_name,
        direction,
        theoretical_throughput,
        average_tolerance="0.95",
        minimum_tolerance="0.8",
        omit=60,
        end=660,
        **kwargs
    ):
        """
        Check unidirectional Throughput.


        :param dt_name: str, alias name for created data transfer.
        :param direction: str, direction of the target traffic to be checked. E.G UL / DL.
        :param theoretical_throughput: float, theory value unit in Mbps!! E.G 10 means 10Mbit / sec.
        :param average_tolerance: Optional[str], acceptable percent. E.G 95%.
        :param minimum_tolerance: Optional[str], minimum percentage, E.G 85%.
        :param omit: it is a delay in seconds to start counting the tput ex.
                '60' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput ex.
                '600' - it takes into account data till 600 second of transfer.

        Returns: Dict, raw throughput details info.

        """
        return self.qualcomm_object.check_unidirectional_throughput(
            dt_name=dt_name,
            direction=direction,
            theoretical_throughput=theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
            omit=omit,
            end=end,
        )

    def check_bidirectional_throughput(self, dt_name, **kwargs):
        raise NotImplementedError(
            "Qualcomm do not support check bi direction traffic by iperf for now."
        )
